#define MAX_SIZE 200

int main()
{
	char str[MAX_SIZE];
	scanf("%s", str);

	int n = strlen(str);

	// 前缀和
	int preSum[MAX_SIZE + 1] = {0};
	for(int i=1; i<=n; i++) {
		preSum[i] = preSum[i-1] + str[i-1];
	}

	// i,j是分割点
	for(int i=1; i<n; i++) {
		// sum1 是 0 ~ i-1 范围的ASCII码之和
		int sum1 = preSum[i] - preSum[0];

		for(int j=i+2; j<n; j++) {
			// sum2 是 i + 1 ~ j - 1 范围的ASCII码之和
			int sum2 = preSum[j] - preSum[i+1];

			// 剪枝
			if(sum1 < sum2) break;

			if(sum1 == sum2) {
				// sum3 是 j + 1 ~ n - 1 范围的ASCII码之和
				int sum3 = preSum[n] - preSum[j+1];

				if(sum2 == sum3) {
					printf("%d,%d", i, j);
					return 0;
				}
			}
		}
	}

	printf("0,0");

	return 0;
